/**
 * Type Bridge Utilities
 * 
 * Provides documented, type-safe helpers for boundary assertions
 * where TypeScript's type system cannot fully verify correctness.
 * 
 * These replace raw `as never` casts with named, auditable functions
 * that make the intent clear and the boundary explicit.
 * 
 * Usage categories:
 * 1. mcpArgs<T>()     — MCP tool dispatch: Record<string, unknown> → specific input type
 * 2. enumCast<T>()    — String-to-enum: validated string → union/enum type
 * 3. shapeCast<T>()   — Object shape: partial/unknown object → expected interface
 * 4. unsafeCast<T>()  — Escape hatch: any boundary cast with required reason
 */

// =============================================================================
// Core Bridge Functions
// =============================================================================

/**
 * Cast MCP tool arguments from Record<string, unknown> to a specific input type.
 * Used at the MCP dispatch boundary where args are validated by Zod schemas
 * before reaching the handler function.
 * 
 * @example
 * const result = await reviewContent(mcpArgs<ReviewContentInput>(args));
 */
export function mcpArgs<T>(args: Record<string, unknown>): T {
  return args as unknown as T;
}

/**
 * Cast a validated string to a specific enum or union type.
 * Used when a string value has been validated (e.g., by Zod, includes(), or switch)
 * but TypeScript cannot narrow the type.
 * 
 * @example
 * const surface = enumCast<SurfaceType>(input.surfaceType);
 */
export function enumCast<T extends string>(value: string): T {
  return value as unknown as T;
}

/**
 * Cast an object to a specific shape/interface.
 * Used when an object's structure is known at runtime (e.g., from API response,
 * database query, or configuration) but TypeScript cannot verify it statically.
 * 
 * @example
 * const config = shapeCast<GovernanceConfig>(dbConfig[0].config);
 */
export function shapeCast<T>(value: unknown): T {
  return value as unknown as T;
}

/**
 * General-purpose boundary cast with a required reason string.
 * This is the escape hatch for cases that don't fit the other categories.
 * The reason parameter documents WHY the cast is necessary.
 * 
 * @example
 * const client = unsafeCast<OpenAI>(governedOpenAI, "governed wrapper implements OpenAI interface");
 */
export function unsafeCast<T>(value: unknown, _reason: string): T {
  return value as unknown as T;
}

// =============================================================================
// Specialized Helpers
// =============================================================================

/**
 * Cast an array to a typed array.
 * Used when array contents are known but TypeScript infers never[] or unknown[].
 * 
 * @example
 * const items = typedArray<PolicyVersion>(rawVersions);
 */
export function typedArray<T>(arr: unknown[]): T[] {
  return arr as unknown as T[];
}

/**
 * Create a typed empty array.
 * Replaces `[] as never[]` pattern.
 * 
 * @example
 * const versions = emptyArray<PolicyVersion>();
 */
export function emptyArray<T>(): T[] {
  return [] as T[];
}

/**
 * Cast a response/result from an API call to the expected type.
 * Used at API boundaries where the response shape is known but not statically typed.
 * 
 * @example
 * const data = apiResult<HealthCheckResult>(response.data);
 */
export function apiResult<T>(value: unknown): T {
  return value as unknown as T;
}

/**
 * Cast a configuration object from storage/database to its expected type.
 * Used when config is stored as JSON and retrieved as unknown.
 * 
 * @example
 * const config = configCast<TenantConfig>(dbRow.config);
 */
export function configCast<T>(value: unknown): T {
  return value as unknown as T;
}

