export class ArtifactGenerator {
  private basePath: string;

  constructor(basePath: string = '/reports') {
    this.basePath = basePath;
  }

  /**
   * Generate all artifacts for an agent run
   */
  async generateAllArtifacts(
    runReport: AgentRunReport,
    decisionTrace: DecisionTrace
  ): Promise<GeneratedArtifacts> {
    const gateReport = this.buildGateReport(runReport);

    // Generate JSON artifacts
    const runReportJson = JSON.stringify(runReport, null, 2);
    const gateReportJson = JSON.stringify(gateReport, null, 2);
    const decisionTraceJson = JSON.stringify(decisionTrace, null, 2);

    // Generate Markdown artifacts
    const runReportMd = this.generateRunReportMarkdown(runReport);
    const gateReportMd = this.generateGateReportMarkdown(gateReport);

    // Build artifact paths
    const artifactPath = `${this.basePath}/${runReport.repo}/${runReport.prNumber}/${runReport.runId}`;

