  severity: 'critical' | 'high' | 'medium' | 'low';
  category: string;
  description: string;
  location?: string;
  suggestedFix?: string;
}

export interface BusinessTruthCheck {
  passed: boolean;
  claimsValidated: number;
  claimsRejected: number;
  forbiddenPatternsFound: string[];
  requiredDisclosuresPresent: boolean;
}

export interface IdentityCheck {
  passed: boolean;
  divergenceScore: number;
  canonicalAlignment: number;
  forbiddenIdentitiesFound: string[];
  buyerAlignmentScore: number;
}

export interface PatchRecord {
  patchId: string;
  iteration: number;
  filePath: string;
  changeType: 'add' | 'modify' | 'delete';
  before: string;
  after: string;
  reason: string;
  appliedAt: string;
}

export interface DecisionTrace {
  traceId: string;
  runId: string;
  spans: TraceSpan[];
  startTime: string;
  endTime: string | null;
  totalDuration: number | null;
}

export interface TraceSpan {
  spanId: string;
  parentSpanId: string | null;
  operation: string;
  startTime: string;
  endTime: string;
  duration: number;
  status: 'ok' | 'error';
  attributes: Record<string, unknown>;
