  priority: 'high' | 'medium' | 'low';
  category: string;
  recommendation: string;
  effort: 'low' | 'medium' | 'high';
}

// Create run report
const runReport: AgentRunReport = {
  runId: rollbackRunId,
  surface: targetRun.surface,
  repo: request.repo,
  prNumber: request.prNumber,
  triggeredBy: request.requestedBy,
  triggerType: 'command',
  startedAt: new Date().toISOString(),
  finishedAt: new Date().toISOString(),
  status: 'passed',
  iterations: 1,
  patchesApplied: reversePatches.length,
  tokensUsed: 0,
  proofBlockId,
  previousRunHash: targetRun.runHash,
  runHash: crypto.createHash('sha256')
    .update(`${rollbackRunId}:${targetRun.runHash}:rollback`)
    .digest('hex')
    .slice(0, 32),
  gateDecision: {
    decision: 'pass',
    score: 100,
    threshold: 75,
    rubricScores: [],
    issues: [],
    recommendations: [],
    businessTruthCheck: {
      passed: true,
      claimsValidated: 0,
      claimsRejected: 0,
      forbiddenPatternsFound: [],
      requiredDisclosuresPresent: true,
    },
    identityCheck: {
      passed: true,
      divergenceScore: 0,
      canonicalAlignment: 100,
      forbiddenIdentitiesFound: [],
      buyerAlignmentScore: 100,
