  patches: reversePatches,
  metadata: {
    type: 'rollback',
    targetRunId: request.targetRunId,
    reason: request.reason,
  },
};

// Create decision trace
const trace: DecisionTrace = this.artifactGen.createDecisionTrace(rollbackRunId);
const span = this.artifactGen.addSpan(trace, 'rollback', null, {
  targetRunId: request.targetRunId,
  patchCount: reversePatches.length,
});
this.artifactGen.completeSpan(span);
this.artifactGen.finalizeTrace(trace);

// Generate artifacts
await this.artifactGen.generateAllArtifacts(runReport, trace);

generalLog.info(`[Rollback] Generated proof block: ${proofBlockId}`);

