24	export const CONCESSION_CLASSES = [
25	  "blocked", "cannot", "should_pause", "needs_manual",
26	  "sam_hands", "infeasible", "out_of_scope_capability",
27	];
28	
29	export const VERDICTS = ["continue_search", "concession_allowed"];
