34	export const CONCESSION_MARKERS = [
35	  /\bblocked\b/i, /\bcannot\b/i, /\bcan['’]t\b/i, /\bunable to\b/i,
36	  /\bno (?:way|path|route|mechanism)\b/i, /\bnot possible\b/i,
37	  /\bimpossible\b/i, /\bawait(?:ing)? (?:your|operator|human)\b/i,
38	  /\bneeds? (?:manual|human|operator)\b/i, /\bout of (?:my )?(?:scope|reach)\b/i,
39	  /\bI (?:don['’]t|do not) have (?:access|a tool|the ability)\b/i,
