41	];
42	
43	/** Does this output concede? Detection is deliberately broad. */
44	export function isConcession(text = "") {
45	  const hits = CONCESSION_MARKERS.filter((re) => re.test(text));
46	  return { conceding: hits.length > 0, matched: hits.map(String) };
47	}
48	
49	// The eight fields. Absence is not "unknown" here — it is INSUFFICIENT, and
50	// insufficient means keep going.
51	export const REQUIRED_EVIDENCE = [
52	  "proposed_concession",
53	  "concession_class",
54	  "available_interfaces",
55	  "paths_attempted",
56	  "attempt_results",
57	  "workaround_classes_considered",
58	  "why_each_viable_workaround_failed",
59	  "other_surface_may_hold_capability",
60	];
61	
62	/**
63	 * The gate. Returns `continue_search` unless the evidence is complete AND the
64	 * cross-surface question has actually been answered.
65	 *
66	 * @param {object} ev  the eight fields
67	 * @param {object} opts
68	 *   attemptedSignatures: paths already tried in earlier rounds (loop control)
69	 *   round: which exhaustion round this is
70	 */
71	export function concessionGate(ev = {}, opts = {}) {
72	  const round = opts.round ?? 1;
73	  const maxRounds = opts.maxRounds ?? 3;
74	  const missing = REQUIRED_EVIDENCE.filter((f) => {
75	    const v = ev[f];
76	    if (v === undefined || v === null) return true;
77	    if (Array.isArray(v)) return v.length === 0;
78	    if (typeof v === "string") return v.trim().length === 0;
79	    return false;
80	  });
81	
82	  const reasons = [];
83	  let verdict = "concession_allowed";
84	  const block = (r) => { verdict = "continue_search"; reasons.push(r); };
85	
86	  if (missing.length) block(`incomplete exhaustion evidence — missing: ${missing.join(", ")}`);
87	
88	  if (!CONCESSION_CLASSES.includes(ev.concession_class))
89	    block(`concession_class '${ev.concession_class}' is not a registered class`);
90	
91	  // THE FIELD THE REAL FAILURE TURNED ON. A worker whose local surface lacks a
92	  // tool has established local absence, never system absence. This must be
93	  // answered with an enumeration, not an intuition.
94	  const cross = ev.other_surface_may_hold_capability;
95	  if (cross && typeof cross === "object") {
96	    if (cross.enumerated !== true)
97	      block("cross-surface capability search was NOT performed — local absence is not system absence");
98	    else if (Array.isArray(cross.surfaces_with_capability) && cross.surfaces_with_capability.length > 0)
99	      block(`another surface holds the capability: ${cross.surfaces_with_capability.join(", ")} — route through it instead of conceding`);
100	  } else if (!missing.includes("other_surface_may_hold_capability")) {
101	    block("other_surface_may_hold_capability must be a structured enumeration, not a prose assertion");
102	  }
103	
104	  // Attempts must be REAL: a path listed but never executed is a plan, not an
105	  // attempt, and the whole point is that intention is not evidence.
106	  const attempts = Array.isArray(ev.paths_attempted) ? ev.paths_attempted : [];
107	  const results = Array.isArray(ev.attempt_results) ? ev.attempt_results : [];
108	  if (attempts.length && results.length < attempts.length)
109	    block(`${attempts.length} paths listed but only ${results.length} carry results — an unexecuted path is not an attempt`);
110	
111	  // LOOP PROTECTION. Exhaustion terminates: a round that surfaced no new path
112	  // is evidence the search is done, and the round ceiling is absolute.
113	  const sigs = new Set(opts.attemptedSignatures || []);
114	  const fresh = attempts.filter((a) => !sigs.has(typeof a === "string" ? a : JSON.stringify(a)));
115	  if (verdict === "continue_search" && round >= maxRounds) {
116	    verdict = "concession_allowed";
117	    reasons.push(`round ceiling ${maxRounds} reached — conceding to avoid an endless workaround loop, with the gaps above recorded as UNRESOLVED rather than searched`);
118	  } else if (verdict === "continue_search" && round > 1 && fresh.length === 0) {
119	    verdict = "concession_allowed";
120	    reasons.push("this round surfaced NO path not already attempted — the search has converged, which is what exhaustion means");
121	  }
122	
123	  return {
124	    artifact: "concession_gate",
125	    verdict,
126	    round,
127	    missing_evidence: missing,
128	    new_paths_this_round: fresh.length,
129	    reasons,
130	    binding:
131	      verdict === "continue_search"
132	        ? "The concession MAY NOT be emitted. Continue searching, then re-submit with the gaps above closed."
133	        : "Concession permitted on the recorded evidence.",
134	    principle:
135	      "A worker may not decide for itself that it has exhausted its options. The goal is not 'never stop' — it is " +
136	      "'never stop while unsearched agency remains'.",
137	  };
138	}
